// @generated by project-forge — visual-render.mjs (self-contained Monochrome Focus Studio HTML/CSS/SVG/JS renderer)
import { sha256Text } from './git-core.mjs'
import {
  escapeHtml,
  escapeJsonForScript,
  escapeXml,
  truncateLabel,
} from './visual-layout.mjs'
import { buildClientScript, buildStylesCss } from './visual-render-assets.mjs'
import {
  MAX_PROTOTYPE_SRCDOC_BYTES,
  renderBlueprintLandingHtml,
  renderCommandPaletteHtml,
  renderDialogsHtml,
  renderDiffRowsHtml,
  renderFocusCardHtml,
  renderPrototypeSlot,
  renderPrototypeSwitcher,
  renderQuickLookModalHtml,
} from './visual-render-panels.mjs'

export { MAX_PROTOTYPE_SRCDOC_BYTES, renderPrototypeSlot }

const DIFF_LABELS = { added: '新增', modified: '修改', removed: '拟移除', impacted: '受波及' }
const VERDICT_LABELS = {
  SYNCED: '已同步',
  CHANGED: '有变更',
  DRAFT: '草稿',
  CONFIRMED: '已确认',
  STALE: '待重审',
}

function localizeVerdictStatus(raw) {
  const key = String(raw || 'SYNCED').trim()
  return VERDICT_LABELS[key.toUpperCase()] || key
}

export function buildGeneratedHeaderLine({ mode = 'architecture-map', featureMapSha256 = '' } = {}) {
  const kind = mode === 'visual-brief' ? 'visual-brief' : 'architecture-map'
  const sha = /^[0-9a-f]{64}$/i.test(String(featureMapSha256 || ''))
    ? String(featureMapSha256).toLowerCase()
    : sha256Text(String(featureMapSha256 || ''))
  return `<!-- @generated by project-forge ${kind}; DO NOT EDIT — schema=v2 feature-map-sha256=${sha} -->`
}

function renderZoomFloatHtml(vpId) {
  return `<div class="pf-zoom-float"><button class="pf-btn pf-btn-sm pf-btn-ghost" type="button" data-zoom-action="out" data-zoom-target="${vpId}" aria-label="缩小">-</button><button class="pf-btn pf-btn-sm pf-btn-ghost pf-zoom-readout" type="button" data-zoom-action="reset" data-zoom-target="${vpId}" data-zoom-label>100%</button><button class="pf-btn pf-btn-sm pf-btn-ghost" type="button" data-zoom-action="in" data-zoom-target="${vpId}" aria-label="放大">+</button><button class="pf-btn pf-btn-sm pf-btn-ghost" type="button" data-zoom-action="fit" data-zoom-target="${vpId}">适配画布</button><button class="pf-btn pf-btn-sm pf-btn-ghost" type="button" data-zoom-action="reset-layout" data-zoom-target="${vpId}" hidden>重置布局</button><span class="pf-zoom-hint">拖拽 · 滚轮缩放</span></div>`
}

function renderFocusBarHtml(tree, hasActiveDiff) {
  const domBtns = (tree.domains || []).map((d) => `<button type="button" class="pf-seg-btn" data-domain-filter="${escapeHtml(d.id)}"><span class="pf-dot" style="--dc:${escapeXml(d.palette?.stroke || '#64748B')}"></span>${escapeHtml(d.shortTitle)}</button>`).join('')
  const diffBtn = `<button id="btn-only-diff" type="button" class="pf-seg-btn"${hasActiveDiff ? '' : ' hidden disabled'}>只看改动</button>`
  const edgeBtn = `<button id="btn-edge-mode" type="button" class="pf-seg-btn">连线：标准</button>`
  return `<div id="pf-focus-bar" class="pf-focus-bar"><div class="pf-seg"><button type="button" class="pf-seg-btn is-active" data-domain-filter="">全部域</button>${domBtns}</div><div class="pf-seg">${diffBtn}${edgeBtn}</div></div>`
}

function formatNodeCue(node) {
  const st = node.diffState
  if (st !== 'added' && st !== 'modified' && st !== 'removed') return ''
  const d = node.changeDetail || {}
  if (d.before && d.after) return truncateLabel(`${d.before} → ${d.after}`, 34)
  if (d.reason) return truncateLabel(d.replacementId ? `${d.reason} · 替代:${d.replacementId}` : d.reason, 34)
  if (d.note) return truncateLabel(d.note, 34)
  return node.shortSummary || ''
}

function formatNodeSubtitle(node) {
  const st = node.diffState || 'context'
  if (st === 'added' || st === 'modified' || st === 'removed') return formatNodeCue(node)
  const summary = truncateLabel(node.shortSummary || '', 30)
  if (summary) return summary
  return `${(node.modules || []).length} 模块 · ${(node.tests || []).length} 测试`
}

function renderNodeCardHtml(node) {
  const st = node.diffState || 'context'
  const diffText = DIFF_LABELS[st] || ''
  const pill = diffText ? `<span class="pf-pill pf-pill-${escapeXml(st)}">${escapeXml(diffText)}</span>` : ''
  const titleCls = st === 'removed' ? 'pf-node-title pf-node-title-removed' : 'pf-node-title'
  const sub = formatNodeSubtitle(node)
  const cueHtml = sub ? `<div class="pf-node-cue">${escapeHtml(sub)}</div>` : ''
  return `<div class="pf-node pf-diff-${escapeXml(st)}" tabindex="0" role="button" title="${escapeHtml(node.title)}" data-node-id="${escapeXml(node.id)}" style="left:${node.x}px;top:${node.y}px;width:${node.w}px;height:${node.h}px">${pill}<div class="${titleCls}">${escapeHtml(node.shortTitle)}</div>${cueHtml}</div>`
}

function renderDomainTreeStage(tree) {
  const zonesHtml = tree.domains.map((dom) => {
    const desc = dom.shortDescription ? `<div class="pf-domain-desc">${escapeHtml(dom.shortDescription)}</div>` : ''
    const dc = escapeXml(dom.palette?.stroke || '#64748B')
    return `<div class="pf-domain-box" data-domain-id="${escapeXml(dom.id)}" style="left:${dom.x}px;top:${dom.y}px;width:${dom.w}px;height:${dom.h}px;--dc:${dc}"><div class="pf-domain-head" style="min-height:${dom.domHeaderH}px"><div class="pf-domain-title-row"><span class="pf-dot"></span><span class="pf-domain-title">${escapeHtml(dom.shortTitle)}</span><span class="pf-domain-meta">${dom.featureCount}</span></div>${desc}</div></div>`
  }).join('')

  const edgeXml = tree.edges.map((edge) => {
    const st = edge.edgeState || (edge.impacted ? 'impacted' : 'context')
    const cls = st !== 'context' ? `pf-edge pf-edge-${escapeXml(st)}` : 'pf-edge'
    return `<path class="${cls}" data-from-id="${escapeXml(edge.fromId)}" data-to-id="${escapeXml(edge.toId)}" d="${escapeXml(edge.pathD)}" marker-end="url(#pf-arrow)" />`
  }).join('\n')

  const nodesHtml = tree.nodes.map((node) => renderNodeCardHtml(node)).join('\n')

  return [
    `<div id="stage-tree" class="pf-stage" style="width:${tree.width}px;height:${tree.height}px">`,
    zonesHtml,
    `<svg id="svg-tree" class="pf-svg" viewBox="0 0 ${tree.width} ${tree.height}" width="${tree.width}" height="${tree.height}" role="img" aria-label="领域与功能架构全景图"><defs><marker id="pf-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 1 L 10 5 L 0 9 z" fill="currentColor" /></marker></defs><g class="pf-edges-layer">${edgeXml}</g></svg>`,
    nodesHtml,
    '</div>',
  ].join('\n')
}

function renderFlowDagStage(flow) {
  const stageHeads = (flow.stages || []).map((st) => `<div class="pf-stage-head" style="left:${st.x}px;top:${st.y}px;width:${st.w}px">${escapeHtml(st.title)}</div>`).join('')
  const lanesHtml = flow.lanes.map((lane) => {
    const dc = escapeXml(lane.palette?.stroke || '#64748B')
    return `<div class="pf-lane" data-lane-id="${escapeXml(lane.id)}" style="left:${lane.x}px;top:${lane.y}px;width:${lane.w}px;height:${lane.h}px;--dc:${dc}"><div class="pf-lane-head" style="width:${lane.labelW}px"><span class="pf-dot"></span><span>${escapeHtml(lane.shortTitle)}</span></div></div>`
  }).join('')

  const edgeXml = flow.edges.map((edge) => {
    const st = edge.edgeState || (edge.impacted ? 'impacted' : 'context')
    const cls = st !== 'context' ? `pf-edge pf-edge-${escapeXml(st)}` : 'pf-edge'
    return `<path class="${cls}" data-from-id="${escapeXml(edge.fromId)}" data-to-id="${escapeXml(edge.toId)}" d="${escapeXml(edge.pathD)}" marker-end="url(#pf-flow-arrow)" />`
  }).join('\n')

  const nodesHtml = flow.nodes.map((node) => renderNodeCardHtml(node)).join('\n')

  return [
    `<div id="stage-flow" class="pf-stage" style="width:${flow.width}px;height:${flow.height}px">`,
    stageHeads,
    lanesHtml,
    `<svg id="svg-flow" class="pf-svg" viewBox="0 0 ${flow.width} ${flow.height}" width="${flow.width}" height="${flow.height}" role="img" aria-label="跨功能角色泳道流转图"><defs><marker id="pf-flow-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 1 L 10 5 L 0 9 z" fill="currentColor" /></marker></defs><g class="pf-edges-layer">${edgeXml}</g></svg>`,
    nodesHtml,
    '</div>',
  ].join('\n')
}

function renderFlowBarHtml(flows = []) {
  if (!Array.isArray(flows) || flows.length === 0) return ''
  const allBtn = '<button type="button" class="pf-seg-btn is-active" data-flow-select="">全部泳道总图</button>'
  const flowBtns = flows.map((f) => `<button type="button" class="pf-seg-btn" data-flow-select="${escapeHtml(f.id)}">${escapeHtml(f.title)}</button>`).join('')
  return `<div id="pf-flow-bar" class="pf-flow-bar"><div class="pf-flow-bar-left"><span class="pf-inspector-label">主流程：</span><div class="pf-seg">${allBtn}${flowBtns}</div></div><button id="btn-flow-ribbon-toggle" class="pf-btn pf-btn-sm pf-btn-ghost" type="button" hidden>收起步骤</button></div><div id="pf-flow-ribbon" class="pf-flow-ribbon" hidden></div>`
}

export function renderVisualHtml({ visualModel, featureMapSha256 = '', mode = 'architecture-map' } = {}) {
  const model = visualModel || {}
  const resolvedMode = mode === 'visual-brief' || model.mode === 'visual-brief' ? 'visual-brief' : 'architecture-map'
  const isBrief = resolvedMode === 'visual-brief'
  const headerLine = buildGeneratedHeaderLine({ mode: resolvedMode, featureMapSha256 })
  const title = escapeHtml(model.title || (isBrief ? '实时规划简报' : '架构全景图'))
  const verdict = model.verdict || { status: '已同步', tone: 'pass', summary: '' }
  const verdictLabel = escapeHtml(localizeVerdictStatus(verdict.status || '已同步'))
  const tree = model.tree || { width: 680, height: 400, domains: [], nodes: [], edges: [] }
  const flow = model.flow || { width: 680, height: 320, lanes: [], stages: [], nodes: [], edges: [], flows: [] }
  const flowsList = Array.isArray(flow.flows) ? flow.flows : []
  const prototypes = Array.isArray(model.prototypes) ? model.prototypes : []
  const showDiffTab = !isBrief && Boolean(model.hasActiveDiff)
  const showProtoTab = prototypes.length > 0 || isBrief
  const defaultTab = isBrief ? 'brief' : 'tree'
  const defaultFollowup = isBrief ? '变更蓝图' : '全景架构'

  const compactClientModel = {
    mode: resolvedMode,
    title: model.title || (isBrief ? '实时规划简报' : '架构全景图'),
    tree: {
      domains: tree.domains.map((d) => ({
        id: d.id, row: d.row, col: d.col, innerCols: d.innerCols,
        corridorMidY: d.corridorMidY, topCorridorY: d.topCorridorY,
        leftAisleX: d.leftAisleX, rightAisleX: d.rightAisleX,
      })),
      nodes: tree.nodes.map((n) => ({
        id: n.id, title: n.title, domain: n.domain, domainTitle: n.domainTitle || n.domain,
        diffState: n.diffState, changeDetail: n.changeDetail || null,
        impactReasons: n.impactReasons || [], risk: n.risk, description: n.description || '',
        x: n.x, y: n.y, w: n.w, h: n.h, cx: n.cx, cy: n.cy,
        entrypoints: (n.entrypoints || []).slice(0, 3), modules: [...(n.modules || [])],
        tests: (n.tests || []).slice(0, 8), verifyTools: (n.verifyTools || []).slice(0, 6),
        docAnchors: (n.docAnchors || []).slice(0, 6),
      })),
      edges: tree.edges.map((e) => ({ fromId: e.fromId, toId: e.toId })),
    },
    flow: {
      nodes: flow.nodes.map((n) => ({ id: n.id, x: n.x, y: n.y, w: n.w, h: n.h, cx: n.cx, cy: n.cy })),
      flows: flowsList.map((fl) => ({ id: fl.id, title: fl.title, featureIds: fl.featureIds || [], steps: fl.steps || [] })),
    },
    walkthrough: (model.walkthrough || []).map((w) => ({ targetId: w.targetId, title: w.title, detail: w.detail })),
  }

  const tabsHtml = [
    isBrief ? '<button class="pf-tab is-active" type="button" data-tab-target="brief">变更蓝图</button>' : '',
    `<button class="pf-tab${defaultTab === 'tree' ? ' is-active' : ''}" type="button" data-tab-target="tree">全景架构</button>`,
    '<button class="pf-tab" type="button" data-tab-target="flow">泳道流转</button>',
    showDiffTab ? '<button class="pf-tab" type="button" data-tab-target="diff">变更影响</button>' : '',
    showProtoTab ? '<button class="pf-tab" type="button" data-tab-target="prototypes">方案原型</button>' : '',
  ].filter(Boolean).join('')

  const html = [
    headerLine,
    '<!DOCTYPE html>',
    '<html lang="zh-CN" data-theme="auto">',
    '<head>',
    '<meta charset="utf-8" />',
    '<meta name="viewport" content="width=device-width, initial-scale=1" />',
    `<title>${title}</title>`,
    `<style>${buildStylesCss({ isBrief })}</style>`,
    '</head>',
    '<body>',
    '<main class="pf-shell">',
    '<header class="pf-topbar">',
    `<div class="pf-top-left"><h1 class="pf-title" title="${title}">${title}</h1><span class="pf-verdict-pill" data-tone="${escapeHtml(verdict.tone || 'pass')}">${verdictLabel}</span><nav class="pf-tabs" aria-label="视图切换">${tabsHtml}</nav></div>`,
    `<div class="pf-controls"><button id="btn-cmdk" class="pf-btn pf-btn-subtle" type="button">搜索模块 ⌘K</button><button id="btn-walk-start" class="pf-btn pf-btn-ghost" type="button"${(model.walkthrough || []).length === 0 ? ' hidden' : ''}>分步导览</button><button id="btn-theme" class="pf-btn pf-btn-ghost" type="button">外观：跟随系统</button><button id="btn-followup-ctx" class="pf-btn pf-btn-primary" type="button" data-followup-panel="${defaultFollowup}">向 AI 提问</button></div>`,
    '</header>',
    '<section class="pf-workspace">',
    isBrief ? `<article class="pf-panel" data-tab-panel="brief">${renderBlueprintLandingHtml(model, verdict, verdictLabel)}</article>` : '',
    `<article class="pf-panel" data-tab-panel="tree"${defaultTab === 'tree' ? '' : ' hidden'}>${renderFocusBarHtml(tree, Boolean(model.hasActiveDiff))}<div class="pf-canvas-wrap"><div id="vp-tree" class="pf-viewport">\n${renderDomainTreeStage(tree)}\n</div>${renderZoomFloatHtml('vp-tree')}</div></article>`,
    `<article class="pf-panel" data-tab-panel="flow" hidden>${renderFlowBarHtml(flowsList)}<div class="pf-canvas-wrap"><div id="vp-flow" class="pf-viewport">\n${renderFlowDagStage(flow)}\n</div>${renderZoomFloatHtml('vp-flow')}</div></article>`,
    showDiffTab ? `<article class="pf-panel" data-tab-panel="diff" hidden><div class="pf-scroll-panel"><div class="pf-chg-grid">${renderDiffRowsHtml(tree.nodes, tree.edges)}</div></div></article>` : '',
    showProtoTab ? `<article class="pf-panel" data-tab-panel="prototypes" hidden><div class="pf-panel-head"><h2 class="pf-panel-title">方案原型对比</h2><div class="pf-controls">${renderPrototypeSwitcher(prototypes)}</div></div><div id="pf-proto-grid" class="pf-proto-grid">${renderPrototypeSlot(prototypes)}</div></article>` : '',
    '</section>',
    '</main>',
    renderFocusCardHtml(),
    renderQuickLookModalHtml(),
    renderCommandPaletteHtml(tree, Boolean(model.hasActiveDiff)),
    renderDialogsHtml(),
    `<script id="pf-visual-data" type="application/json">${escapeJsonForScript(compactClientModel)}</script>`,
    `<script>\n${buildClientScript()}\n</script>`,
    '</body>',
    '</html>',
    '',
  ].filter((x) => x !== '').join('\n')

  return {
    html,
    bytes: Buffer.byteLength(html, 'utf8'),
    sha256: sha256Text(html),
    headerLine,
  }
}
